import{_ as r,a0 as a,w as n,s as l,ao as d,I as p,x as e,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"我的第一个系统管理员错误 | LCTT x X-CMD","titleTemplate":false,"description":"我的第一个系统管理员错误 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我的第一个系统管理员错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我的第一个系统管理员错误 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180702 My first sysadmin mistake","title":"我的第一个系统管理员错误","tag":"201807","desc":""},"relativePath":"201807/20180702 My first sysadmin mistake.md","filePath":"[post].md"}'),m={name:"201807/20180702 My first sysadmin mistake.md"};function u(f,t,T,k,x,C){const s=a("Link");return n(),l("div",null,[t[15]||(t[15]=d('<h1 id="我的第一个系统管理员错误" tabindex="-1">我的第一个系统管理员错误 <a class="header-anchor" href="#我的第一个系统管理员错误" aria-label="Permalink to “我的第一个系统管理员错误”">​</a></h1><blockquote><p>如何在崩溃的局面中集中精力寻找解决方案。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_mistakes.png?itok=dN0OoIl5" alt=""></p><p>如果你在 IT 领域工作，你知道事情永远不会像你想象的那样完好。在某些时候，你会遇到错误或出现问题，你最终必须解决问题。这就是系统管理员的工作。</p><p>作为人类，我们都会犯错误。我们不是已经犯错，就是即将犯错。结果，我们最终还必须解决自己的错误。总是这样。我们都会失误、敲错字母或犯错。</p><p>作为一名年轻的系统管理员，我艰难地学到了这一课。我犯了一个大错。但是多亏了上级的指导，我学会了不去纠缠于我的错误，而是制定一个“错误策略”来做正确的事情。从错误中吸取教训。克服它，继续前进。</p><p>我的第一份工作是一家小公司的 Unix 系统管理员。真的，我是一名生嫩的系统管理员，但我大部分时间都独自工作。我们是一个小型 IT 团队，只有我们三个人。我是 20 或 30 台 Unix 工作站和服务器的唯一系统管理员。另外两个支持 Windows 服务器和桌面。</p><p>任何阅读这篇文章的系统管理员都不会对此感到意外，作为一个不成熟的初级系统管理员，我最终在错误的目录中运行了 <code>rm</code> 命令——作为 root 用户。我以为我正在为我们的某个程序删除一些陈旧的缓存文件。相反，我错误地清除了 <code>/etc</code> 目录中的所有文件。糟糕。</p><p>我意识到犯了错误是看到了一条错误消息，“<code>rm</code> 无法删除某些子目录”。但缓存目录应该只包含文件！我立即停止了 <code>rm</code> 命令，看看我做了什么。然后我惊慌失措。一下子，无数个想法涌入了我的脑中。我刚刚销毁了一台重要的服务器吗？系统会怎么样？我会被解雇吗？</p><p>幸运的是，我运行的是 <code>rm *</code> 而不是 <code>rm -rf *</code>，因此我只删除了文件。子目录仍在那里。但这并没有让我感觉更好。</p><p>我立刻去找我的主管告诉她我做了什么。她看到我对自己的错误感到愚蠢，但这是我犯的。尽管紧迫，她花了几分钟时间跟我做了一些指导。她说：“你不是第一个这样做的人，在你这种情况下，别人会怎么做？”这帮助我平静下来并专注。我开始更少考虑我刚刚做的愚蠢事情，而更多地考虑我接下来要做的事情。</p><p>我做了一个简单的策略：不要重启服务器。使用相同的系统作为模板，并重建 <code>/etc</code> 目录。</p><p>制定了行动计划后，剩下的就很容易了。只需运行正确的命令即可从另一台服务器复制 <code>/etc</code> 文件并编辑配置，使其与系统匹配。多亏了我对所有东西都做记录的习惯，我使用已有的文档进行最后的调整。我避免了完全恢复服务器，这意味着一个巨大的宕机事件。</p><p>可以肯定的是，我从这个错误中吸取了教训。在接下来作为系统管理员的日子中，我总是在运行任何命令之前确认我所在的目录。</p><p>我还学习了构建“错误策略”的价值。当事情出错时，恐慌并思考接下来可能发生的所有坏事是很自然的。这是人性。但是制定一个“错误策略”可以帮助我不再担心出了什么问题，而是专注于让事情变得更好。我仍然会想一下，但是知道我接下来的步骤可以让我“克服它”。</p><hr>',16)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(s,{href:"https://opensource.com/article/18/7/my-first-sysadmin-mistake"},{default:i(()=>[...t[0]||(t[0]=[e("https://opensource.com/article/18/7/my-first-sysadmin-mistake",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),o(s,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...t[2]||(t[2]=[e("Jim Hall",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:i(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),o(s,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const b=r(m,[["render",u]]);export{L as __pageData,b as default};
